dashboard.definition:
{
    "title": "Labor und Radiologie",
    "description": "LIS-Befunde mit TAT und KIS-Zustellung, RIS-Auftraege je Modalitaet und DICOM-Speicherungen im PACS",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Zeitraum",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        },
        "input_dept": {
            "type": "input.dropdown",
            "title": "Abteilung",
            "options": {
                "items": [
                    {
                        "label": "Alle Abteilungen",
                        "value": "*"
                    },
                    {
                        "label": "Innere Medizin (INN)",
                        "value": "INN"
                    },
                    {
                        "label": "Kardiologie (KAR)",
                        "value": "KAR"
                    },
                    {
                        "label": "Neurologie (NEU)",
                        "value": "NEU"
                    },
                    {
                        "label": "Onkologie (ONK)",
                        "value": "ONK"
                    },
                    {
                        "label": "Allgemeinchirurgie (CHI)",
                        "value": "CHI"
                    },
                    {
                        "label": "Unfallchirurgie/Orthopaedie (UCH)",
                        "value": "UCH"
                    },
                    {
                        "label": "Urologie (URO)",
                        "value": "URO"
                    },
                    {
                        "label": "HNO",
                        "value": "HNO"
                    },
                    {
                        "label": "Anaesthesie/OP (ANA)",
                        "value": "ANA"
                    },
                    {
                        "label": "Intensivmedizin (ICU)",
                        "value": "ICU"
                    },
                    {
                        "label": "Notaufnahme (ZNA)",
                        "value": "ZNA"
                    },
                    {
                        "label": "Radiologie (RAD)",
                        "value": "RAD"
                    },
                    {
                        "label": "Gynaekologie/Geburtshilfe (GYN)",
                        "value": "GYN"
                    },
                    {
                        "label": "Paediatrie (PAED)",
                        "value": "PAED"
                    },
                    {
                        "label": "Psychiatrie (PSY)",
                        "value": "PSY"
                    }
                ],
                "token": "dept",
                "defaultValue": "*"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        }
    },
    "dataSources": {
        "ds_lis": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:lis:result\" department=\"$dept$\"\n| fields Wert Zeit _time c category count critical delivered_to_kis delivery_status flag m n pos priority tat_min test_code test_name u unit value ward",
                "enableSmartSources": true
            },
            "name": "Laborbefunde"
        },
        "ds_k_results": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count as Befunde"
            }
        },
        "ds_k_crit": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval c=if(critical=\"true\" OR critical=\"1\", 1, 0) | timechart span=30m sum(c) as \"Kritische Werte\""
            }
        },
        "ds_k_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where priority=\"Notfall\" | timechart span=30m avg(tat_min) as \"TAT Notfall\""
            }
        },
        "ds_k_undeliv": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| eval u=if(delivered_to_kis=\"false\" OR delivered_to_kis=\"0\", 1, 0) | timechart span=10m sum(u) as \"Nicht im KIS\""
            }
        },
        "ds_k_flu": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where test_code=\"INFLU\" | stats count(eval(value=\"positiv\")) as pos count as n | eval \"Influenza positiv %\"=if(n>0, round(100 * pos / n, 1), 0) | fields \"Influenza positiv %\""
            }
        },
        "ds_cat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=30m count by category"
            }
        },
        "ds_tat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where category!=\"Mikrobiologie\" | timechart span=30m avg(tat_min) by priority"
            }
        },
        "ds_delivery": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| timechart span=10m count by delivery_status"
            }
        },
        "ds_crit_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_lis",
                "query": "| where flag=\"HH\" OR flag=\"LL\"\n| eval Zeit=strftime(_time, \"%H:%M\"), Wert=value.\" \".unit\n| table Zeit ward test_name Wert flag priority delivery_status\n| rename ward as Station test_name as Test flag as Flag priority as Prioritaet delivery_status as Zustellung | head 40\n| appendpipe [| stats count | where count=0 | eval Zeit=\"Keine kritischen Werte im Zeitraum\" | fields - count]"
            }
        },
        "ds_ris": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:ris:order\" department=\"$dept$\"\n| fields Tage Zeit _time count device_id exam modality order_id original_device priority reason status wait_days",
                "enableSmartSources": true
            },
            "name": "RIS-Auftraege"
        },
        "ds_modality": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| chart count over modality by status"
            }
        },
        "ds_wait": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where priority=\"Routine\" | stats avg(wait_days) as \"Wartezeit (Tage)\" by modality | eval \"Wartezeit (Tage)\"=round('Wartezeit (Tage)', 1)"
            }
        },
        "ds_moved": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| where status=\"umgeplant\"\n| eval Zeit=strftime(_time, \"%H:%M\") | table Zeit order_id exam original_device device_id reason wait_days\n| rename order_id as Auftrag exam as Untersuchung original_device as \"Geplant auf\" device_id as \"Neu auf\" reason as Grund wait_days as \"Wartezeit (Tage)\"\n| appendpipe [| stats count | where count=0 | eval Zeit=\"Keine umgeplanten Untersuchungen im Zeitraum\" | fields - count]"
            }
        },
        "ds_pacs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pacs:dicom\" | timechart span=30m sum(size_mb) as MB by modality",
                "enableSmartSources": true
            },
            "name": "PACS Datenvolumen"
        },
        "ds_pacs_fail": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh sourcetype=\"sakh:pacs:dicom\" status!=\"Success\" | stats count as Fehler by device_id status | rename device_id as Modalitaet status as Fehlerbild | appendpipe [| stats count | where count=0 | eval Modalitaet=\"Keine Speicherfehler im Zeitraum\" | fields - count]",
                "enableSmartSources": true
            }
        },
        "ds_device": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_ris",
                "query": "| stats count by device_id | sort - count | head 12"
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_studio",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_studio/images/nav_care.svg",
