        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_results"
            },
            "options": {
                "majorColor": "#f472b6",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_crit"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 5,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 5,
                        "to": 10,
                        "value": "#ffc53d"
                    },
                    {
                        "from": 10,
                        "value": "#ff4d6d"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_tat"
            },
