                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#22d3ee"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 45,
                        "value": "#34e2a0"
                    },
                    {
                        "from": 45,
                        "to": 60,
                        "value": "#ffc53d"
                    },
                    {
