        "viz_09": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_crit_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 10,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#0b1630",
                    "rowColors": "#eaf2ff",
                    "headerColor": "#9fb1c9"
                },
                "columnFormat": {
                    "Zustellung": {
                        "rowBackgroundColors": "> table | seriesByName(\"Zustellung\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
